// HasEvaluationSnapshot applies the HasEdge predicate on the "evaluation_snapshot" edge.
func HasEvaluationSnapshot() predicate.WorkInsightKindEvaluationSnapshot {
	return predicate.WorkInsightKindEvaluationSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, EvaluationSnapshotTable, EvaluationSnapshotColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEvaluationSnapshotWith applies the HasEdge predicate on the "evaluation_snapshot" edge with a given conditions (other predicates).
func HasEvaluationSnapshotWith(preds ...predicate.WorkInsightEvaluationSnapshot) predicate.WorkInsightKindEvaluationSnapshot {
	return predicate.WorkInsightKindEvaluationSnapshot(func(s *sql.Selector) {
		step := newEvaluationSnapshotStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasLatestEvidence applies the HasEdge predicate on the "latest_evidence" edge.
func HasLatestEvidence() predicate.WorkInsightKindEvaluationSnapshot {
	return predicate.WorkInsightKindEvaluationSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, LatestEvidenceTable, LatestEvidenceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLatestEvidenceWith applies the HasEdge predicate on the "latest_evidence" edge with a given conditions (other predicates).
func HasLatestEvidenceWith(preds ...predicate.Evidence) predicate.WorkInsightKindEvaluationSnapshot {
	return predicate.WorkInsightKindEvaluationSnapshot(func(s *sql.Selector) {
		step := newLatestEvidenceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkInsightKindEvaluationSnapshot) predicate.WorkInsightKindEvaluationSnapshot {
	return predicate.WorkInsightKindEvaluationSnapshot(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkInsightKindEvaluationSnapshot) predicate.WorkInsightKindEvaluationSnapshot {
	return predicate.WorkInsightKindEvaluationSnapshot(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkInsightKindEvaluationSnapshot) predicate.WorkInsightKindEvaluationSnapshot {
	return predicate.WorkInsightKindEvaluationSnapshot(sql.NotPredicates(p))
}
